      {|<path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/>|}
    | File_pen ->
      (* lucide: file-pen *)
      {|<path d="M12.5 22H18a2 2 0 0 0 2-2V7l-5-5H6a2 2 0 0 0-2 2v9.5"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M13.378 15.626a1 1 0 1 0-3.004-3.004l-5.01 5.012a2 2 0 0 0-.506.854l-.837 2.87a.5.5 0 0 0 .62.62l2.87-.837a2 2 0 0 0 .854-.506z"/>|}
    | Folder_search ->
      (* lucide: folder-search *)
      {|<path d="M10.7 20H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.69.9l.81 1.2a2 2 0 0 0 1.67.9H20a2 2 0 0 1 2 2v4.1"/><path d="m21 21-1.9-1.9"/><circle cx="17" cy="17" r="3"/>|}
    | Text_search ->
      (* lucide: text-search *)
      {|<path d="M21 6H3"/><path d="M10 12H3"/><path d="M10 18H3"/><circle cx="17" cy="15" r="3"/><path d="m21 19-1.9-1.9"/>|}
    | Globe ->
      (* lucide: globe *)
      {|<circle cx="12" cy="12" r="10"/><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"/><path d="M2 12h20"/>|}
  ;;

  let name t = String.lowercase (Sexp.to_string (sexp_of_t t))

  let view ?(cls = "") t =
    Node.inner_html_svg
      ~override_vdom_for_testing:
        (lazy (Node.create "icon" ~attrs:[ Attr.class_ (name t) ] []))
      ~tag:"svg"
      ~attrs:
        [ Attr.class_ (String.strip ("icon " ^ cls))
        ; Attr.create "viewBox" "0 0 24 24"
        ; Attr.create "fill" "none"
        ; Attr.create "stroke" "currentColor"
        ; Attr.create "stroke-width" "2"
        ; Attr.create "stroke-linecap" "round"
        ; Attr.create "stroke-linejoin" "round"
        ; Attr.create "aria-hidden" "true"
        ]
      ~this_html_is_sanitized_and_is_totally_safe_trust_me:(paths t)
      ()
  ;;

  let svg ?(cls = "") t =
    sprintf
      {|<svg class="%s" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%s</svg>|}
      (String.strip ("icon " ^ cls))
      (paths t)
  ;;
end

let icon = Icon.view

let mark ?(cls = "") ?label t =
  Node.span
    ~attrs:
      (Attr.class_ (String.strip ("mark " ^ cls))
       ::
       (match label with
        | Some l ->
          [ Attr.title l; Attr.role "img"; Attr.create "aria-label" l ]
        | None -> [ Attr.create "aria-hidden" "true" ]))
    [ icon t ]
;;

(* Loon's Checkbox and Radio_group item, drawn (the row is the control). *)
let check ?(radio = false) on =
  let look =
    match radio, on with
    | false, false ->
      "check flex size-4 shrink-0 items-center justify-center rounded-[4px] \
       border border-input dark:bg-input/30"
    | false, true ->
      "check on flex size-4 shrink-0 items-center justify-center rounded-[4px] \
       border border-primary bg-primary text-primary-foreground"
    | true, false ->
      "check radio flex size-4 shrink-0 items-center justify-center \
       rounded-full border border-input dark:bg-input/30"
    | true, true ->
      "check radio on flex size-4 shrink-0 items-center justify-center \
       rounded-full border border-primary bg-primary"
  in
  Node.span
    ~attrs:[ Attr.class_ look; Attr.create "aria-hidden" "true" ]
    (match radio, on with
     | false, true -> [ icon ~cls:"size-3.5" Check ]
     | true, true ->
       [ Node.span
           ~attrs:[ Attr.class_ "size-2 rounded-full bg-primary-foreground" ]
           []
       ]
     | _, false -> [])
;;

let caret (ev : Dom_html.event Js.t) =
  Js.Opt.case
    ev##.target
    (fun () -> None)
    (fun target ->
       match Dom_html.tagged target with
       | Textarea t ->
         Some
           (Utf16.byte_offset
              (Js.to_string t##.value)
              ~utf16:t##.selectionStart)
       | Input i ->
         Some
           (Utf16.byte_offset
              (Js.to_string i##.value)
              ~utf16:i##.selectionStart)
       | _ -> None)
;;

let rec inert (node : Node.t) : Node.t =
  match node with
  | Element e ->
    Element
      (Node.Element.map_attrs e ~f:(fun a ->
         Attr.many [ a; Attr.create "inert" "" ]))
  | Lazy { key; t } -> Lazy { key; t = lazy (inert (Lazy.force t)) }
  | Fragment nodes -> Fragment (List.map nodes ~f:inert)
  | (None | Text _ | Widget _) as node -> node
;;
